        ExistingPackageSummaryTextBlock.Text = $"{package.Name} · {package.ValidityDisplay} · {package.DataQuotaDisplay} · {package.PriceDisplay}. سيتم ربط هذا التعريف بالنظام الحالي دون إنشاء تعريف تجاري مكرر.";
        var previous = _catalog.Bindings.FirstOrDefault(b => b.ProviderKey == _providerKey && b.PackageId == package.Id);
        if (previous is not null) FillBindingFields(previous);
    }

