    private void SavePackageButton_Click(object sender, RoutedEventArgs e)
    {
        EditorStatusTextBlock.Text = string.Empty;
        try
        {
            _catalog = DemoPackageStore.Load();
            if (_bindingOnly)
            {
                SaveBindingOnly();
                return;
            }

            var name = PackageNameTextBox.Text.Trim();
            if (string.IsNullOrWhiteSpace(name)) { ShowValidation("أدخل اسم الباقة."); return; }
            var excludeId = _originalPackage?.Id;
            if (_catalog.Packages.Any(p => p.Id != excludeId && string.Equals(p.Name.Trim(), name, StringComparison.CurrentCultureIgnoreCase)))
            {
                ShowValidation("يوجد تعريف باقة بهذا الاسم. استخدم «ربط باقة موجودة» إذا كنت تريد إتاحتها في النظام الآخر بدل تكرار التعريف التجاري."); return;
            }

            var unlimitedValidity = UnlimitedValidityCheckBox.IsChecked == true;
            int validityDays;
            if (unlimitedValidity)
            {
                validityDays = 0;
            }
            else if (!TryInt(ValidityDaysTextBox, out validityDays) || validityDays < 1)
            {
                ShowValidation("الصلاحية يجب أن تكون يومًا واحدًا على الأقل، أو اختر «بلا انتهاء تقويمي»."); return;
            }

            if (!TryInt(UptimeHoursTextBox, out var uptimeHours) || uptimeHours < 0 ||
                !TryInt(UptimeMinutesTextBox, out var uptimeMinutes) || uptimeMinutes < 0 || uptimeMinutes > 59)
            { ShowValidation("حد الاستخدام الزمني غير صحيح. أدخل ساعات صحيحة ودقائق من 0 إلى 59."); return; }

            var unlimitedData = UnlimitedDataCheckBox.IsChecked == true;
            decimal quotaAmount;
            if (unlimitedData)
            {
                quotaAmount = 0;
            }
            else if (!TryDecimal(DataQuotaAmountTextBox, out quotaAmount) || quotaAmount <= 0)
            {
                ShowValidation("حصة البيانات يجب أن تكون أكبر من صفر أو اختر «بلا حد للبيانات»."); return;
            }
            var quotaUnit = SelectedTag(DataQuotaUnitComboBox, "MB");
            if (!TryDecimal(DownloadMbpsTextBox, out var downloadMbps) || downloadMbps < 0 ||
                !TryDecimal(UploadMbpsTextBox, out var uploadMbps) || uploadMbps < 0)
            { ShowValidation("سرعة التنزيل والرفع يجب أن تكون صفرًا أو قيمة موجبة."); return; }
            if (!TryDecimal(SalePriceTextBox, out var salePrice) || salePrice < 0 ||
                !TryDecimal(CardDisplayPriceTextBox, out var cardPrice) || cardPrice < 0)
            { ShowValidation("السعر وسعر الطباعة يجب أن يكونا صفرًا أو قيمة موجبة."); return; }

            var commissionEnabled = CommissionEnabledCheckBox.IsChecked == true;
            if (!TryDecimal(CommissionValueTextBox, out var commissionValue) || commissionValue < 0)
            { ShowValidation("قيمة العمولة غير صحيحة."); return; }
            var commissionMode = SelectedTag(CommissionModeComboBox, "Percentage");
            if (commissionEnabled && commissionMode == "Percentage" && commissionValue > 100)
            { ShowValidation("العمولة المئوية لا يمكن أن تتجاوز 100%."); return; }
            if (commissionEnabled && commissionMode == "Percentage" && commissionValue == 0)
            { ShowValidation("أدخل نسبة عمولة أكبر من صفر أو أوقف العمولة."); return; }

            var notificationsEnabled = NotificationsEnabledCheckBox.IsChecked == true;
            if (!TryInt(FirstAlertPercentTextBox, out var alert1) || !TryInt(SecondAlertPercentTextBox, out var alert2) ||
                alert1 < 1 || alert1 > 100 || alert2 < 1 || alert2 > 100 || (notificationsEnabled && alert1 >= alert2))
            { ShowValidation("نسب التنبيه يجب أن تكون بين 1 و100، ويجب أن يكون التنبيه الأول أقل من الثاني."); return; }

            var package = _originalPackage?.Copy() ?? new DemoServicePackage();
            package.Name = name;
            package.ValidityDays = unlimitedValidity ? 0 : validityDays;
            package.UnlimitedValidity = unlimitedValidity;
            package.UptimeHours = uptimeHours;
            package.UptimeMinutes = uptimeMinutes;
            package.DataQuotaAmount = unlimitedData ? 0 : quotaAmount;
            package.DataQuotaUnit = quotaUnit;
            package.UnlimitedData = unlimitedData;
            package.DownloadMbps = downloadMbps;
            package.UploadMbps = uploadMbps;
            package.SalePriceYer = salePrice;
            package.CardDisplayPriceYer = cardPrice;
            package.CommissionEnabled = commissionEnabled;
            package.CommissionMode = commissionMode;
            package.CommissionValue = commissionEnabled ? commissionValue : 0;
            package.PreserveUsageOnRouterInterruption = PreserveUsageOnRouterInterruptionCheckBox.IsChecked == true;
            package.PreserveTimeOnRouterInterruption = PreserveTimeOnRouterInterruptionCheckBox.IsChecked == true;
            package.RecordHotSpotSessions = RecordHotSpotSessionsCheckBox.IsChecked == true;
            package.NotificationsEnabled = notificationsEnabled;
            package.FirstAlertPercent = alert1;
            package.SecondAlertPercent = alert2;
            package.Notes = string.Empty;
            package.UpdatedAt = DateTimeOffset.Now;

            var binding = _originalBinding?.Copy() ?? new DemoPackageBinding { ProviderKey = _providerKey, PackageId = package.Id };
            if (binding.ProviderKey != _providerKey) throw new InvalidOperationException("لا يمكن تعديل ربط تابع لنظام آخر من هذه الشاشة.");
            if (!TryBuildBinding(binding, out var bindingError)) { ShowValidation(bindingError); return; }

            if (_originalPackage is null)
            {
                package.Id = Guid.NewGuid().ToString("N");
                binding.PackageId = package.Id;
                package.CreatedAt = DateTimeOffset.Now;
                _catalog.Packages.Add(package);
                binding.CreatedAt = DateTimeOffset.Now;
                _catalog.Bindings.Add(binding);
            }
            else
            {
                var packageIndex = _catalog.Packages.FindIndex(p => p.Id == _originalPackage.Id);
                var bindingIndex = _catalog.Bindings.FindIndex(b => b.Id == _originalBinding!.Id && b.ProviderKey == _providerKey);
                if (packageIndex < 0 || bindingIndex < 0) throw new InvalidOperationException("تعريف الباقة أو الربط غير موجود في كتالوج الباقات.");
                package.Id = _originalPackage.Id;
                package.CreatedAt = _originalPackage.CreatedAt;
                binding.Id = _originalBinding!.Id;
                binding.PackageId = package.Id;
                binding.CreatedAt = _originalBinding.CreatedAt;
                binding.UpdatedAt = DateTimeOffset.Now;
                _catalog.Packages[packageIndex] = package;
                _catalog.Bindings[bindingIndex] = binding;
            }

            DemoPackageStore.Save(_catalog);
            DialogResult = true;
        }
        catch (Exception ex)
        {
            ShowValidation("تعذر حفظ الباقة: " + ex.Message);
        }
    }

    private void SaveBindingOnly()
    {
        if (ExistingPackageComboBox.SelectedItem is not DemoServicePackage selected)
        { ShowValidation("اختر تعريف باقة لربطه بهذا النظام."); return; }
        var package = _catalog.Packages.FirstOrDefault(p => p.Id == selected.Id && !p.IsArchived);
        if (package is null) { ShowValidation("تعريف الباقة المحدد لم يعد متاحًا."); return; }

        var binding = _catalog.Bindings.FirstOrDefault(b => b.PackageId == package.Id && b.ProviderKey == _providerKey);
        if (binding is null)
        {
            binding = new DemoPackageBinding { Id = Guid.NewGuid().ToString("N"), PackageId = package.Id, ProviderKey = _providerKey, CreatedAt = DateTimeOffset.Now };
            _catalog.Bindings.Add(binding);
        }
        else if (binding.IsEnabled)
        {
            ShowValidation("هذه الباقة مرتبطة بالفعل بهذا النظام."); return;
        }

        if (!TryBuildBinding(binding, out var bindingError)) { ShowValidation(bindingError); return; }
        binding.IsEnabled = true;
        binding.UpdatedAt = DateTimeOffset.Now;
        DemoPackageStore.Save(_catalog);
        DialogResult = true;
    }

    private bool TryBuildBinding(DemoPackageBinding binding, out string error)
    {
        error = string.Empty;
        binding.ProviderKey = _providerKey;
        if (_providerKey == "hotspot")
        {
            binding.HotSpotProfile = SelectedTag(HotSpotProfileComboBox, "default");
            binding.HotSpotServer = SelectedTag(HotSpotServerComboBox, "all");
            binding.HotSpotUsesUserManager = HotSpotUsesUserManagerCheckBox.IsChecked == true;
            binding.HotSpotUserManagerProfile = SelectedTag(HotSpotUserManagerProfileComboBox, "UM-1H-500M");
            if (!int.TryParse(SelectedTag(HotSpotSharedUsersComboBox, "1"), NumberStyles.Integer, CultureInfo.InvariantCulture, out var sharedUsers) || sharedUsers < 0)
            { error = "عدد الجلسات المتزامنة غير صحيح."; return false; }
            binding.HotSpotSharedUsers = sharedUsers;
            return true;
        }

        binding.UserManagerProfile = SelectedTag(UserManagerProfileComboBox, "UM-1H-500M");
        binding.UserManagerLimitation = SelectedTag(UserManagerLimitationComboBox, "limit-hour-500mb-2m");
        binding.UserManagerGroup = SelectedTag(UserManagerGroupComboBox, "default");
        binding.UserManagerStartsWhen = SelectedTag(UserManagerStartsWhenComboBox, "first-auth");
        binding.UserManagerSharedOverride = SelectedTag(UserManagerSharedOverrideComboBox, "off");
        binding.UseSchedule = UseScheduleCheckBox.IsChecked == true;
        binding.AccessFrom = AccessFromTextBox.Text.Trim();
        binding.AccessUntil = AccessUntilTextBox.Text.Trim();
        binding.AccessDays = GetSelectedDays();
        if (binding.UseSchedule)
        {
            if (binding.AccessDays.Count == 0) { error = "اختر يومًا واحدًا على الأقل لفترة السماح."; return false; }
            if (!TimeSpan.TryParse(binding.AccessFrom, CultureInfo.InvariantCulture, out var from) ||
                !TimeSpan.TryParse(binding.AccessUntil, CultureInfo.InvariantCulture, out var until) ||
                from < TimeSpan.Zero || until > TimeSpan.FromDays(1) || from >= until)
            { error = "وقت البداية والنهاية غير صحيح؛ استخدم صيغة 24 ساعة واجعل البداية قبل النهاية في اليوم نفسه."; return false; }
        }
        return true;
    }

    private List<string> GetSelectedDays()
    {
        var days = new List<string>();
        if (SaturdayCheckBox.IsChecked == true) days.Add("السبت");
        if (SundayCheckBox.IsChecked == true) days.Add("الأحد");
        if (MondayCheckBox.IsChecked == true) days.Add("الإثنين");
        if (TuesdayCheckBox.IsChecked == true) days.Add("الثلاثاء");
        if (WednesdayCheckBox.IsChecked == true) days.Add("الأربعاء");
        if (ThursdayCheckBox.IsChecked == true) days.Add("الخميس");
        if (FridayCheckBox.IsChecked == true) days.Add("الجمعة");
        return days;
    }

    private static string SelectedTag(ComboBox combo, string fallback)
        => (combo.SelectedItem as ComboBoxItem)?.Tag?.ToString() ?? fallback;

    private static void SelectComboByTag(ComboBox combo, string? tag)
    {
        foreach (var item in combo.Items.OfType<ComboBoxItem>())
        {
            if (string.Equals(item.Tag?.ToString(), tag, StringComparison.OrdinalIgnoreCase))
            { combo.SelectedItem = item; return; }
        }
        if (combo.Items.Count > 0) combo.SelectedIndex = 0;
    }

    private static bool TryInt(TextBox box, out int value)
        => int.TryParse(NormalizeDigits(box.Text), NumberStyles.Integer, CultureInfo.InvariantCulture, out value);

    private static bool TryDecimal(TextBox box, out decimal value)
    {
        var text = NormalizeDigits(box.Text).Trim().Replace('٫', '.');
        return decimal.TryParse(text, NumberStyles.Number, CultureInfo.CurrentCulture, out value) ||
               decimal.TryParse(text, NumberStyles.Number, CultureInfo.InvariantCulture, out value);
    }

    private static string NormalizeDigits(string? value)
    {
        if (string.IsNullOrEmpty(value)) return string.Empty;
        var chars = value.ToCharArray();
        for (var i = 0; i < chars.Length; i++)
        {
            if (chars[i] >= '٠' && chars[i] <= '٩') chars[i] = (char)('0' + (chars[i] - '٠'));
            else if (chars[i] >= '۰' && chars[i] <= '۹') chars[i] = (char)('0' + (chars[i] - '۰'));
        }
        return new string(chars);
    }

    private void ShowValidation(string message)
    {
        EditorStatusTextBlock.Text = message;
        EditorStatusTextBlock.Foreground = System.Windows.Media.Brushes.Firebrick;
    }

    private void CancelButton_Click(object sender, RoutedEventArgs e) => DialogResult = false;
